{
  "interpretation": {
    "name": "TightenF25AtSt1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten all fasteners of forklift variant F25 at station st1 on line 1 using nutrunner NR7, so the blocked unit can be released.",
    "constraints": [
      "NR7 must be reserved exclusively and its lease renewed before every physical use",
      "NR7 must be transported from the crib to st1 (via agvexecutor) before configure-tool and tighten-fasteners",
      "The tightening program must come only from get-program, with no literal torque or tolerance values in the Recipe",
      "The tightening result must be evaluated against the program and recorded for traceability",
      "The reservation must be released after use, and NR7 returned to the crib as it is a shared tool"
    ],
    "preference": "",
    "priority": "high",
    "horizon": "Immediate, single execution",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-f25-st1-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f25-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-f25"],
            "dep": ["get-f25-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-f25",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-f25",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-f25", "get-f25-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-f25",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-f25"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
